import CmuxWorkspaces
import Foundation

/// Collects the local-tmux bindings a session snapshot would reattach.
///
/// Workspace panels, workspace Docks, and window Docks all restore terminals,
/// so all three are scanned. Only commands generated by the local-tmux profile
/// yield a binding; arbitrary persisted commands are ignored.
struct LocalTmuxStartupRestoreBindings {
    let policy: WorkspaceSessionRestorePolicyService<SurfaceResumeBindingSnapshot>

    func bindings(in snapshot: AppSessionSnapshot) -> Set<LocalTmuxRestoreBinding> {
        var result = Set<LocalTmuxRestoreBinding>()
        func collect(_ panels: [SessionPanelSnapshot]) {
            for panel in panels {
                if let binding = policy.localTmuxRestoreBinding(panel.terminal?.tmuxStartCommand) {
                    result.insert(binding)
                }
            }
        }
        for window in snapshot.windows {
            collect(window.dock?.panels ?? [])
            for workspace in window.tabManager.workspaces {
                collect(workspace.panels)
                collect(workspace.dock?.panels ?? [])
            }
        }
        return result
    }
}
